local converted, missing = 0, 0
for i = 1, #PRE9_SABER_LIST do
	local e = PRE9_SABER_LIST[i]
	local t = ObjectTemplates[crcString(e.path)]
	if t == nil then
		missing = missing + 1
		print("pre9_sabers: MISSING stock template " .. e.path)
	else
		t.damageType = PRE9_DAMAGE_TYPE
		t.forceCost = 0
		t.xpType = PRE9_XP[e.family]
		-- pre9: make per-type saber toughness mods functional (stock
		-- weapons reference only lightsaber_toughness)
		t.defenderToughnessModifiers = { "lightsaber_toughness", e.family .. "lightsaber_toughness" }
		if t.minDamage ~= nil then t.minDamage = t.minDamage * PRE9_DAMAGE_MULT end
		if t.maxDamage ~= nil then t.maxDamage = t.maxDamage * PRE9_DAMAGE_MULT end
		if t.experimentalSubGroupTitles ~= nil and t.experimentalMin ~= nil and t.experimentalMax ~= nil then
			for j = 1, #t.experimentalSubGroupTitles do
				local title = t.experimentalSubGroupTitles[j]
				if title == "forcecost" then
					t.experimentalMin[j] = 0
					t.experimentalMax[j] = 0
				elseif title == "mindamage" or title == "maxdamage" then
					t.experimentalMin[j] = t.experimentalMin[j] * PRE9_DAMAGE_MULT
					t.experimentalMax[j] = t.experimentalMax[j] * PRE9_DAMAGE_MULT
				end
			end
		end
		ObjectTemplates:addTemplate(t, e.path)
		converted = converted + 1
	end
end
print("pre9_sabers: converted " .. converted .. " saber templates, " .. missing .. " missing, mult " .. PRE9_DAMAGE_MULT)
